import{_ as t,o as n,c as a,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Tenant Maintenance Mode & Suspension","description":"Put every tenant workspace into maintenance with a bypass link and IP allow list, or suspend a single workspace, while the central app stays online.","frontmatter":{"title":"Tenant Maintenance Mode & Suspension","description":"Put every tenant workspace into maintenance with a bypass link and IP allow list, or suspend a single workspace, while the central app stays online.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/core/maintenance-and-suspension.html"}],["meta",{"property":"og:title","content":"Tenant Maintenance Mode & Suspension"}],["meta",{"property":"og:description","content":"Put every tenant workspace into maintenance with a bypass link and IP allow list, or suspend a single workspace, while the central app stays online."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/core/maintenance-and-suspension.html"}],["meta",{"name":"twitter:title","content":"Tenant Maintenance Mode & Suspension"}],["meta",{"name":"twitter:description","content":"Put every tenant workspace into maintenance with a bypass link and IP allow list, or suspend a single workspace, while the central app stays online."}]]},"headers":[],"relativePath":"docs/core/maintenance-and-suspension.md","filePath":"docs/core/maintenance-and-suspension.md","lastUpdated":1790486087000}'),o={name:"docs/core/maintenance-and-suspension.md"};function d(i,e,c,r,l,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="maintenance-suspension" tabindex="-1">Maintenance &amp; suspension <a class="header-anchor" href="#maintenance-suspension" aria-label="Permalink to &quot;Maintenance &amp; suspension&quot;">​</a></h1><p>Two mechanisms block access to tenant workspaces without touching the central app: <strong>maintenance mode</strong> takes every workspace offline for planned work, <strong>suspension</strong> locks a single tenant.</p><table tabindex="0"><thead><tr><th></th><th>Maintenance mode</th><th>Suspension</th></tr></thead><tbody><tr><td>Scope</td><td><strong>All</strong> tenant workspaces</td><td>One tenant</td></tr><tr><td>Set in</td><td>Setup → Tenant Settings</td><td>Tenant edit form (Workspace status)</td></tr><tr><td>Page</td><td><code>auth/Maintenance</code> (HTTP 503)</td><td><code>auth/Suspended</code> (HTTP 403)</td></tr><tr><td>Still reachable</td><td>Login, two-factor, passkey login, logout, bypass link</td><td>Logout only</td></tr><tr><td>Bypass</td><td>Secret link, IP/CIDR allow list</td><td>None</td></tr><tr><td>Middleware</td><td><code>EnsureTenantIsNotInMaintenance</code></td><td><code>EnsureTenantIsNotSuspended</code></td></tr></tbody></table><p>The central app is never affected by either mechanism.</p><div class="info custom-block"><p class="custom-block-title">Laravel&#39;s own maintenance mode</p><p>This is separate from <code>php artisan down</code>, which takes the whole application (central and tenants) offline.</p></div><h2 id="maintenance-mode" tabindex="-1">Maintenance mode <a class="header-anchor" href="#maintenance-mode" aria-label="Permalink to &quot;Maintenance mode&quot;">​</a></h2><p>Turn it on in <strong>Setup → Tenant Settings</strong> (<code>/setup/tenant-settings</code>, central only, permission <code>Manage Tenant Maintenance</code>).</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th><th>Purpose</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>Turns maintenance on for every tenant</td></tr><tr><td><code>message</code></td><td>max 500 chars</td><td>Shown on the maintenance page</td></tr><tr><td><code>secret</code></td><td>8-64 chars, <code>alpha_dash</code></td><td>Enables the bypass link</td></tr><tr><td><code>allowed_ips</code></td><td>up to 50 IPs or CIDR ranges</td><td>These IPs are never blocked</td></tr></tbody></table><p>How a tenant request is handled while maintenance is on:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>login / two-factor / passkey login / logout / bypass route → allowed</span></span>
<span class="line"><span>IP in allowed_ips                                          → allowed</span></span>
<span class="line"><span>valid bypass cookie                                        → allowed</span></span>
<span class="line"><span>anything else                                              → maintenance page (503)</span></span></code></pre></div><h3 id="bypass-link" tabindex="-1">Bypass link <a class="header-anchor" href="#bypass-link" aria-label="Permalink to &quot;Bypass link&quot;">​</a></h3><p>Lets your team use a workspace while it is in maintenance:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://acme.vue.test/maintenance/bypass/{secret}</span></span></code></pre></div><ul><li>Sign in to the tenant first; the route requires a signed-in tenant user (<code>auth:tenant</code>).</li><li>A valid secret sets the <code>tenant_maintenance_bypass</code> cookie for <strong>12 hours</strong> and redirects to <code>/</code>.</li><li>The cookie holds an HMAC of the secret with <code>APP_KEY</code>, so changing the secret invalidates existing bypass cookies.</li></ul><h3 id="ip-allow-list" tabindex="-1">IP allow list <a class="header-anchor" href="#ip-allow-list" aria-label="Permalink to &quot;IP allow list&quot;">​</a></h3><p>Requests from any listed IP or CIDR range pass straight through. Entries are validated by the <code>IpAddressOrCidr</code> rule and checked with Symfony&#39;s <code>IpUtils::checkIp()</code>.</p><p><strong>Related files</strong></p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>Modules/Tenant/Data/MaintenanceModeData.php</code></td><td>Fields and validation</td></tr><tr><td><code>Modules/Tenant/Services/TenantMaintenanceService.php</code></td><td>Reads and stores the setting (central <code>settings</code> table, key <code>tenant_maintenance</code>), bypass and IP checks</td></tr><tr><td><code>Modules/Tenant/Http/Middleware/EnsureTenantIsNotInMaintenance.php</code></td><td>Blocks requests, lists the open routes</td></tr><tr><td><code>Modules/Tenant/Http/Controllers/TenantMaintenanceBypassController.php</code></td><td>Sets the bypass cookie</td></tr><tr><td><code>Modules/Tenant/Rules/IpAddressOrCidr.php</code></td><td>IP / CIDR validation</td></tr></tbody></table><h2 id="suspension" tabindex="-1">Suspension <a class="header-anchor" href="#suspension" aria-label="Permalink to &quot;Suspension&quot;">​</a></h2><p>Set a tenant&#39;s <strong>Workspace status</strong> to <strong>Suspended</strong> in the tenant edit form, optionally with a <strong>status message</strong> (max 500 chars).</p><p>On every request to that tenant&#39;s domains, <code>EnsureTenantIsNotSuspended</code> renders <code>auth/Suspended</code> with the company name and message (HTTP 403). Only <code>logout</code> still works. Set the status back to Active or Trial to restore access.</p><p>See <a href="/docs/core/multi-tenancy.html#workspace-status">Multi-tenancy → Workspace status</a>.</p>`,22)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
